#!/usr/bin/env node

/*
 * Builds apps/web/src/lib/ai/mcpToolDefs.generated.ts - the tool catalogue of the
 * MCP bridge, as a TypeScript module the editor can hand to a large model.
 *
 * The single source stays scripts/layerling-mcp-tools.mjs: the built-in AI
 * assistant and the external MCP clients (Claude, Codex, Gemini) then describe
 * the editor with one set of words. Run it through `npm run ai:tools`; predev
 * and prebuild run it as well, and tests/unit/aiToolDefsSync.test.ts fails the
 * moment the generated file is older than the catalogue.
 */

import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const repositoryRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const OUT = join(repositoryRoot, "apps", "web", "src", "lib", "ai", "mcpToolDefs.generated.ts");

const { tools } = await import(pathToFileURL(join(repositoryRoot, "scripts", "layerling-mcp-tools.mjs")).href);
if (!Array.isArray(tools) || tools.length === 0) {
  throw new Error("layerling-mcp-tools.mjs exported no tools to generate from");
}

// One tool per line: the file stays a plain data table, like the printer presets.
const lines = tools.map((tool) => `  ${JSON.stringify(tool)},`);

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(
  OUT,
  `// Generated by scripts/generate-ai-mcp-tool-defs.mjs - do not edit by hand.
// Source: scripts/layerling-mcp-tools.mjs, the tool catalogue of the MCP bridge,
// so the built-in assistant and the external MCP clients share one description.
// Refresh with \`npm run ai:tools\` (predev and prebuild run it as well).

export type LayerlingMcpToolDef = {
  name: string;
  description: string;
  inputSchema: {
    type?: string;
    properties?: Record<string, unknown>;
    required?: string[];
    [key: string]: unknown;
  };
};

export const LAYERLING_MCP_TOOL_DEFS: readonly LayerlingMcpToolDef[] = [
${lines.join("\n")}
];
`,
);

console.log(`ai:tools: wrote ${tools.length} tool definitions to ${OUT}`);
